import cpmpy as cp
import json

# Input data
n = 8  # Number of words to find
# End of input data

# Model definition
model = cp.Model()

# Decision Variables: words[i][p] in {0,1,2,3} representing {A,C,G,T}
words = cp.intvar(0, 3, shape=(n, 8), name="words")

# Constraints

# 1) Each word has exactly 4 symbols from {C=1, G=2}
for i in range(n):
    # Count positions where the letter is C (1) or G (2)
    cg_count = cp.sum([(words[i, p] == 1) + (words[i, p] == 2) for p in range(8)])
    model += (cg_count == 4)

# 2) Hamming distance >=4 between any two distinct words
for i in range(n):
    for j in range(i+1, n):
        hd_ij = cp.sum([words[i, p] != words[j, p] for p in range(8)])
        model += (hd_ij >= 4)

# 3) For any words x (index i) and y (index j), 
#    Hamming distance between reverse(x) and complement(y) >=4
#    reverse(x)[p] = x[7-p], complement(y)[p] = 3 - y[p]
for i in range(n):
    for j in range(n):
        hd_rc = cp.sum([words[i, 7-p] != (3 - words[j, p]) for p in range(8)])
        model += (hd_rc >= 4)

# 4) Symmetry breaking: fix the first word to AAAACCCC => [0,0,0,0,1,1,1,1]
for p in range(4):
    model += (words[0, p] == 0)  # A
for p in range(4, 8):
    model += (words[0, p] == 1)  # C

# Solve and print
if model.solve():
    solution = {
        'words': words.value().tolist()
    }
    print(json.dumps(solution, indent=4))
else:
    print("No solution found.")
